"use client";

/**
 * Data layer for the Reconstructions explorer.
 *
 * Assets live in `public/reconstructions/` (generated by
 * `pruebas/scripts/build-recon-web-data.ts` from the CubeRoot + reco.nz
 * crawls):
 *   - index.json               → list metadata for every solve
 *   - data/chunk-XXX.json      → full records (scramble, phases, text, stats,
 *                                baked recognition)
 *
 * Both are fetched lazily and cached in module scope. The recognition data
 * per phase (case number, slot, verified) was baked at build time.
 */
import type { Solve } from "@/types";
import type {
  CubeMoveEvent,
  OrientationTimeline,
  SolveMetrics,
} from "@cubeforge/types";
import {
  conjugatePhaseStream,
  conjugateToBaseFrame,
  tokenize,
} from "@cubeforge/math-core";

// ─── Types (mirror of the build script output) ──────────────────────────────

export type ReconSource = "cuberoot" | "reconz";
export type ReconMethodGroup = "CFOP" | "Roux" | "Other";

export interface ReconIndexEntry {
  key: string;
  source: ReconSource;
  id: number;
  solver: string;
  time: number; // seconds
  date: string | null;
  competition: string;
  method: string;
  methodGroup: ReconMethodGroup;
  /** Normalized puzzle label ("3x3", "2x2", "pyraminx", …). */
  puzzle: string;
  stm: number | null;
  tps: number | null;
  tags: string[];
  url: string | null;
}

export interface ReconPhase {
  label: string;
  /** Display notation — a DIRECT parse of the raw phase (wide moves, slices
   *  and rotations keep their written form, e.g. `r'`, `x'`). This is what
   *  the Steps table shows, exactly like the reconstructor wrote it. */
  moves: string;
  /** Raw token count of the display notation (each written move = 1). */
  moveCount: number;
  /** Conjugated cube-frame moves for the 3D replay (rotations folded; wide
   *  moves decomposed into face + slice, BOTH kept — the engine animates
   *  M/E/S as middle-layer turns). Computed at load by `normalizeReconMoves`;
   *  absent in baked data. */
  replayMoves?: string;
  /** Length of `replayMoves` — matches the replay event array 1:1. */
  replayMoveCount?: number;
  recog?: {
    caseNumber: string | null;
    slot: "FR" | "FL" | "BL" | "BR" | null;
    verified: boolean;
  } | null;
}

export interface ReconFullRecord extends ReconIndexEntry {
  scramble: string;
  text: string;
  phases: ReconPhase[];
  /** Reconstructor credits (reco.nz: Brest/Stewy/…, CubeRoot: reconer). */
  reconstructor?: string | null;
  /** Single-solve record tag (WR/NR/PR…) when the source reports one. */
  record?: string | null;
  /** CubeRoot: round average for the solve (seconds). */
  average?: number | null;
  /** CubeRoot: solve number within the round (1..5). */
  solveNum?: number | null;
  /** CubeRoot: cube model used. */
  cube?: string | null;
  /** CubeRoot: ISO country code. */
  country?: string | null;
  /** CubeRoot: official flag ("wca"…). */
  official?: string | null;
  /** CubeRoot: WCA competition id. */
  compWcaId?: string | null;
  stats: {
    crossStm?: number | null;
    f2l?: number | null;
    ll?: number | null;
    yRot?: number | null;
    regrip?: number | null;
    freePair?: number | null;
    sMove?: number | null;
    crossColor?: string | null;
    videoUrl?: string | null;
    recordAverage?: string | null;
  };
  recognition: {
    finalSolved: boolean;
    inspection: string;
    crossVerified: boolean;
  };
  /** Whole-cube rotations (x/y/z) in the stream, computed at load — the 3D
   *  engine cannot animate them, so they are folded into the conjugated
   *  moves and never shown as replay steps (same as the smartcube path). */
  rotationCount: number;
  /** Synthetic orientation keyframes ([eventIndex, orientationIndex]) so the
   *  3D replay rotates the cube to the solver's perspective like the
   *  smartcube path (empty when the record has no rotations).
   *
   *  IMPORTANT: indices are in EVENT space — the same space as the replay
   *  `moves` array, which includes the slice half of wide moves. Do NOT
   *  index this against the face-only display moves of `p.moves`. */
  orientationTimeline: OrientationTimeline;
}

interface ReconIndexFile {
  version: number;
  count: number;
  chunkSize: number;
  solves: ReconIndexEntry[];
}

// ─── Fetch + cache ──────────────────────────────────────────────────────────

let indexPromise: Promise<ReconIndexFile> | null = null;
const recordCache = new Map<string, Promise<ReconFullRecord | null>>();

function loadIndex(): Promise<ReconIndexFile> {
  indexPromise ??= fetch(`${import.meta.env.BASE_URL}reconstructions/index.json`).then(
    (r) => {
      if (!r.ok) throw new Error(`reconstructions index: HTTP ${r.status}`);
      return r.json() as Promise<ReconIndexFile>;
    },
  );
  return indexPromise;
}

/** All list entries (memoised). Throws on fetch failure. */
export function fetchReconIndex(): Promise<ReconIndexEntry[]> {
  return loadIndex().then((f) => f.solves);
}

/** Load the full record for one reconstruction key (cached). */
export function fetchReconRecord(key: string): Promise<ReconFullRecord | null> {
  const cached = recordCache.get(key);
  if (cached) return cached;

  const promise = (async () => {
    const index = await loadIndex();
    const rank = index.solves.findIndex((e) => e.key === key);
    if (rank < 0) return null;
    const chunk = Math.floor(rank / index.chunkSize);
    const file = `${import.meta.env.BASE_URL}reconstructions/data/chunk-${String(chunk).padStart(3, "0")}.json`;
    const res = await fetch(file);
    if (!res.ok) throw new Error(`reconstructions chunk ${chunk}: HTTP ${res.status}`);
    const data = (await res.json()) as { solves: ReconFullRecord[] };
    const record = data.solves.find((s) => s.key === key) ?? null;
    if (record) normalizeReconMoves(record);
    return record;
  })();

  recordCache.set(key, promise);
  return promise;
}

// ─── Replay helper ──────────────────────────────────────────────────────────

/** Valid outer-face turns — the tokens `conjugatePhaseStream` counts when
 *  emitting orientation keyframes (mirror of its `isSliceToken`). */
const FACE_MOVE_RE = /^[URFDLB][2']?$/;

/** Valid animatable moves — outer faces PLUS slices. The 3D engine now
 *  animates M/E/S as middle-layer turns (FACE_ROTATION_MAP), so the slice
 *  half of a wide move becomes a real replay event instead of being dropped. */
const ANIMATABLE_MOVE_RE = /^[URFDLBMES][2']?$/;

/**
 * Re-index the synthetic orientation timeline from FACE-move space to EVENT
 * space. `conjugatePhaseStream` counts only outer-face turns (FACE_MOVE_RE)
 * when emitting keyframes; the replay event array now ALSO contains slice
 * turns (each wide move's slice half), so every keyframe's move index must
 * shift by the number of slice tokens before that face turn.
 *
 * The flattened stream is filtered with the SAME regex `notationToReplayMoves`
 * uses, so event indices here are definitionally identical to the replay
 * event array — garbage tokens are dropped in both places and can never
 * cause an off-by-N drift between the two spaces.
 */
function reindexTimelineToEventSpace(
  timeline: OrientationTimeline,
  perPhase: string[][],
): OrientationTimeline {
  if (timeline.length === 0) return timeline;
  const faceToEvent: number[] = [];
  let faceIdx = 0;
  let eventIdx = 0;
  for (const phase of perPhase) {
    for (const token of phase) {
      if (!ANIMATABLE_MOVE_RE.test(token)) continue;
      if (FACE_MOVE_RE.test(token)) faceToEvent[faceIdx++] = eventIdx;
      eventIdx++;
    }
  }
  return timeline.map(([moveIndex, orient]) => [
    faceToEvent[moveIndex] ?? moveIndex,
    orient,
  ]);
}

/**
 * Normalize a record's phase moves at load time, once.
 *
 * TWO representations are kept apart:
 *
 * 1. **Display (`p.moves` / `p.moveCount`)** — a DIRECT parse of the raw
 *    phase: `tokenize(..., { expandWide: false })` splits CubeRoot's glued
 *    tokens ("U'D" → U' + D), Unicode primes and the ↓ ↑ · . separators, but
 *    keeps wide moves (`r'`) and rotations (`x'`) as written. The Steps
 *    table shows exactly what the reconstructor wrote.
 * 2. **Replay (`p.replayMoves` / `p.replayMoveCount`)** — `conjugatePhaseStream`
 *    folds inspection + mid-solve rotations into the cube-fixed frame so
 *    replaying scramble → moves ends SOLVED, keeping BOTH the face and the
 *    slice half of wide moves (the 3D engine animates M/E/S middle layers).
 *
 * The raw `text` is left untouched for copy.
 */
function normalizeReconMoves(record: ReconFullRecord): void {
  const { perPhase, rotationCount, orientationTimeline } = conjugatePhaseStream(
    record.phases.map((p) => tokenize(p.moves)),
  );
  record.rotationCount = rotationCount;
  // The orientation timeline is emitted in FACE-move space (slice turns are
  // not counted); the replay events now include slice turns, so re-index
  // every keyframe to event space for the 3D cube's solver-perspective.
  record.orientationTimeline = reindexTimelineToEventSpace(
    orientationTimeline,
    perPhase,
  );
  record.phases.forEach((p, i) => {
    // Display: direct parse of the raw phase — no wide expansion, so the
    // written notation (r', U2', x') survives for the Steps table.
    const displayTokens = tokenize(p.moves, { expandWide: false });
    p.moves = displayTokens.join(" ");
    p.moveCount = displayTokens.length;
    // Replay: conjugated face + slice moves (garbage tokens can't animate).
    const faceMoves = perPhase[i].filter((t) => ANIMATABLE_MOVE_RE.test(t));
    p.replayMoves = faceMoves.join(" ");
    p.replayMoveCount = faceMoves.length;
  });
  // Scrambles can carry CubeRoot separators too ("↓F2") — tokenize them so
  // the ReplayEngine's applyInitialScramble gets clean elementary tokens.
  record.scramble = tokenize(record.scramble)
    .filter((t) => ANIMATABLE_MOVE_RE.test(t))
    .join(" ");
}

/**
 * Turn a notation string into CubeMoveEvents for the ReplayEngine.
 *
 * `tokenize` first — it splits glued tokens ("U'D"), Unicode primes, wide
 * moves and the ↓ ↑ · . separators. The sequence is then CONJUGATED to the
 * cube-fixed frame (conjugateToBaseFrame): inspection and mid-solve rotations
 * are folded into the moves, so replaying scramble → moves ends SOLVED.
 * Rotations are consumed by the conjugation; face AND slice tokens become
 * events (the ReplayEngine animates M/E/S as middle-layer turns). Events are
 * spaced at a fixed 550ms so the replay timeline is proportional to moves.
 */
export function notationToReplayMoves(notation: string, start = 0): CubeMoveEvent[] {
  const tokens = conjugateToBaseFrame(tokenize(notation));
  const events: CubeMoveEvent[] = [];
  let ts = start;
  for (const token of tokens) {
    if (!ANIMATABLE_MOVE_RE.test(token)) continue; // garbage can't animate
    const face = token[0] as CubeMoveEvent["face"];
    const suffix = token.slice(1);
    const direction = suffix === "2" ? 2 : suffix === "'" ? -1 : 1;
    events.push({
      face,
      direction,
      cubeTimestamp: ts,
      hostTimestamp: ts,
    });
    ts += 550;
  }
  return events;
}

/**
 * Adapt a reconstruction record to the `Solve` shape the ReplaySection
 * consumes (replay canvas + transport + live phase indicator).
 */
export function reconToSolve(record: ReconFullRecord): Solve {
  // Replay path uses the CONJUGATED moves (replayMoves), NOT the raw display
  // moves — rotations are already folded and slices are real events, so the
  // cube ends SOLVED in the 3D replay.
  const allMoves = record.phases.map((p) => p.replayMoves ?? p.moves).join(" ");
  const moves = notationToReplayMoves(allMoves);

  // The synthetic orientation timeline rotates the 3D cube to the solver's
  // perspective during replay (same as the smartcube path), so the displayed
  // notation matches what the reconstructor wrote instead of the physical
  // cube-frame letters.
  const orientationTimeline =
    record.orientationTimeline && record.orientationTimeline.length > 0
      ? record.orientationTimeline
      : undefined;

  // p.replayMoveCount is the CONJUGATED face-move count (normalizeReconMoves),
  // so it matches the replay `moves` array below exactly — rotations are
  // folded into the moves and never counted, same as the smartcube path.
  const phases: SolveMetrics["phases"] = record.phases.map((p) => ({
    phaseName: p.label,
    durationMs: 0,
    moveCount: p.replayMoveCount ?? p.moveCount,
    tps: 0,
    pauseCount: 0,
    pauseTimeMs: 0,
  }));

  const dateTs = record.date ? Date.parse(record.date) : 0;

  return {
    id: record.key,
    time: Math.round(record.time * 1000),
    penalty: "none",
    scramble: record.scramble,
    timestamp: Number.isFinite(dateTs) ? dateTs : 0,
    method: record.method as Solve["method"],
    source: "manual",
    moves,
    orientationTimeline,
    // So 2×2 reconstructions replay on a 2×2 cube (not a 3×3).
    puzzleType:
      record.puzzle === "2x2"
        ? "2x2x2"
        : record.puzzle === "3x3"
          ? "3x3x3"
          : undefined,
    analysis: { phases } as unknown as SolveMetrics,
  };
}
